package com.example.agendapersonal.eventos;

import android.content.*;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;
import com.example.agendapersonal.data.DatabaseHelper;import com.example.agendapersonal.ui.registro.Registro;import com.example.agendapersonal.util.JsonCursorHelper;import com.example.agendapersonal.sync.*;
import org.json.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.nio.charset.StandardCharsets;import java.util.*;

/** Las ocurrencias sin modificaciones se calculan desde la regla; solo las excepciones se guardan. */
public final class SeriesEvento {
 public static final String META="_agenda_recurrencia_v1";
 public static final int SOLO=0,SIGUIENTES=1,TODAS=2;
 private static final String[] CAMPOS={"descripcion","categoria","fecha","hora","personaId","lugar","estadoEspecial","alarmaActivada","anticipacionMinutos","observaciones","serieId"};
 private SeriesEvento(){}
 public static void iniciar(SQLiteDatabase db){db.execSQL("CREATE TABLE IF NOT EXISTS eventos_ocurrencias (evento_id TEXT PRIMARY KEY NOT NULL, serie_id TEXT NOT NULL, ordinal INTEGER NOT NULL, fecha_origen TEXT NOT NULL)");db.execSQL("CREATE INDEX IF NOT EXISTS idx_ocurrencias_serie ON eventos_ocurrencias(serie_id,ordinal)");}
 public static JSONObject metadatos(SQLiteDatabase db,String id)throws JSONException{try(Cursor t=db.rawQuery("SELECT name FROM sqlite_master WHERE name='eventos_ocurrencias' AND type='table'",null)){if(!t.moveToFirst())return null;}try(Cursor c=db.query("eventos_ocurrencias",null,"evento_id=?",new String[]{id},null,null,null)){if(!c.moveToFirst())return null;return new JSONObject().put("serie_id",c.getString(c.getColumnIndexOrThrow("serie_id"))).put("ordinal",c.getLong(c.getColumnIndexOrThrow("ordinal"))).put("fecha_origen",c.getString(c.getColumnIndexOrThrow("fecha_origen")));}}
 public static void guardarIndice(SQLiteDatabase db,String id,JSONObject meta)throws JSONException{String serie=ReglasSync.uuid(meta.getString("serie_id"));long ordinal=meta.getLong("ordinal");if(ordinal<0)throw new IllegalArgumentException("Ocurrencia inválida");String fecha=LocalDate.parse(meta.getString("fecha_origen")).toString();iniciar(db);ContentValues v=new ContentValues();v.put("evento_id",id);v.put("serie_id",serie);v.put("ordinal",ordinal);v.put("fecha_origen",fecha);db.insertWithOnConflict("eventos_ocurrencias",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 private static JSONObject fila(SQLiteDatabase db,String tabla,String id)throws JSONException{try(Cursor c=db.query(tabla,null,"id=?",new String[]{id},null,null,null)){return c.moveToFirst()?JsonCursorHelper.toJsonObject(c):null;}}
 private static Registro registro(JSONObject p)throws JSONException{Registro r=new Registro();Iterator<String>keys=p.keys();while(keys.hasNext()){String k=keys.next();String[]partes=k.split("_");StringBuilder nombre=new StringBuilder(partes[0]);for(int i=1;i<partes.length;i++)nombre.append(Character.toUpperCase(partes[i].charAt(0))).append(partes[i].substring(1));Object v=p.get(k);r.put(nombre.toString(),v==JSONObject.NULL?null:v.toString());}r.put("alarmaActivada",String.valueOf(p.optInt("alarma_activada",0)!=0));return r;}
 private static void anotar(SQLiteDatabase db,Registro r)throws JSONException{JSONObject meta=metadatos(db,r.texto("id"));if(meta!=null){r.put("_serie",meta.getString("serie_id"));r.put("_ordinal",String.valueOf(meta.getLong("ordinal")));r.put("_fechaOrigen",meta.getString("fecha_origen"));}}
 public static Registro cargar(Context c,String id){try(DatabaseHelper h=new DatabaseHelper(c)){JSONObject p=fila(h.getReadableDatabase(),"eventos",id);if(p==null||!p.isNull("deleted_at"))return null;Registro r=registro(p);anotar(h.getReadableDatabase(),r);return r;}catch(JSONException e){throw new IllegalStateException(e);}}
 private static String columna(String c){return c.replaceAll("([a-z])([A-Z])","$1_$2").toLowerCase(Locale.ROOT);}
 private static ContentValues valores(Registro r){ContentValues v=new ContentValues();for(String campo:CAMPOS){String s=r.get(campo);if(campo.equals("alarmaActivada"))v.put(columna(campo),Boolean.parseBoolean(s)?1:0);else if(campo.equals("anticipacionMinutos")){if(s==null||s.isEmpty())v.putNull(columna(campo));else v.put(columna(campo),Integer.parseInt(s));}else v.put(columna(campo),s==null||s.isEmpty()?null:s);}return v;}
 private static JSONObject plantilla(Registro r)throws JSONException{JSONObject t=new JSONObject();for(String campo:CAMPOS)if(!Arrays.asList("fecha","serieId","estadoEspecial").contains(campo))t.put(campo,r.get(campo)==null?JSONObject.NULL:r.get(campo));return t;}
 private static JSONObject segmento(long desde,ReglaRecurrencia regla,JSONObject plantilla)throws JSONException{return new JSONObject().put("desde",desde).put("inicio",regla.inicio.toString()).put("unidad",regla.unidad.name()).put("cada",regla.cada).put("dia",regla.dia).put("mes",regla.mes).put("plantilla",plantilla);}
 private static ReglaRecurrencia regla(JSONObject segmento)throws JSONException{return new ReglaRecurrencia(LocalDate.parse(segmento.getString("inicio")),ReglaRecurrencia.Unidad.valueOf(segmento.getString("unidad")),segmento.getInt("cada"),segmento.optInt("dia",LocalDate.parse(segmento.getString("inicio")).getDayOfMonth()),segmento.optInt("mes",LocalDate.parse(segmento.getString("inicio")).getMonthValue()));}
 private static JSONObject segmentoEn(JSONObject cfg,long ordinal)throws JSONException{JSONArray s=cfg.getJSONArray("segmentos");JSONObject elegido=s.getJSONObject(0);for(int i=0;i<s.length();i++){JSONObject actual=s.getJSONObject(i);if(actual.getLong("desde")<=ordinal)elegido=actual;else break;}return elegido;}
 public static LocalDate fecha(JSONObject cfg,long ordinal)throws JSONException{JSONObject s=segmentoEn(cfg,ordinal);return regla(s).fecha(ordinal-s.getLong("desde"));}
 private static String id(JSONObject cfg,String serie,long ordinal)throws JSONException{return ordinal==0?cfg.getString("evento_inicial"):UUID.nameUUIDFromBytes(("AgendaPersonal:serie:"+serie+":"+ordinal).getBytes(StandardCharsets.UTF_8)).toString();}
 private static Registro virtual(JSONObject serie,JSONObject cfg,long ordinal)throws JSONException{Registro r=new Registro();JSONObject t=segmentoEn(cfg,ordinal).getJSONObject("plantilla");Iterator<String>keys=t.keys();while(keys.hasNext()){String k=keys.next();r.put(k,t.isNull(k)?null:t.get(k).toString());}r.put("id",id(cfg,serie.getString("id"),ordinal));r.put("ownerId",serie.isNull("owner_id")?null:serie.getString("owner_id"));r.put("serieId",serie.getString("id"));r.put("fecha",fecha(cfg,ordinal).toString());r.put("estadoEspecial",null);r.put("revision","1");r.put("createdAt",serie.getString("created_at"));r.put("updatedAt",serie.getString("updated_at"));r.put("_virtual","true");r.put("_serie",serie.getString("id"));r.put("_ordinal",String.valueOf(ordinal));r.put("_fechaOrigen",r.get("fecha"));return r;}
 private static JSONObject configuracion(JSONObject serie)throws JSONException{JSONObject c=new JSONObject(serie.getString("configuracion_personalizada"));if(c.optInt("version")!=1)throw new IllegalArgumentException("Esta serie necesita una versión compatible de la app");return c;}
 public static List<Registro> virtuales(Context c,LocalDate desde,LocalDate hasta){if(desde.isAfter(hasta))return Collections.emptyList();List<Registro>r=new ArrayList<>();try(DatabaseHelper h=new DatabaseHelper(c)){SQLiteDatabase db=h.getReadableDatabase();Set<String> existentes=new HashSet<>();try(Cursor cursor=db.query("eventos",new String[]{"id"},null,null,null,null,null)){while(cursor.moveToNext())existentes.add(cursor.getString(0));}try(Cursor cursor=db.query("series_eventos",null,"deleted_at IS NULL",null,null,null,null)){while(cursor.moveToNext()){JSONObject serie=JsonCursorHelper.toJsonObject(cursor);if(serie.isNull("configuracion_personalizada"))continue;JSONObject cfg=configuracion(serie);LocalDate fin=serie.isNull("fecha_fin")?hasta:LocalDate.parse(serie.getString("fecha_fin"));if(fin.isAfter(hasta))fin=hasta;JSONArray segmentos=cfg.getJSONArray("segmentos");long parar=cfg.optLong("parar_antes",Long.MAX_VALUE);for(int j=0;j<segmentos.length();j++){JSONObject s=segmentos.getJSONObject(j);long inicio=s.getLong("desde"),limite=j+1<segmentos.length()?segmentos.getJSONObject(j+1).getLong("desde"):Long.MAX_VALUE;limite=Math.min(limite,parar);ReglaRecurrencia regla=regla(s);long k=regla.aproximar(desde);while(inicio+k<limite){LocalDate f=regla.fecha(k);if(f.isAfter(fin))break;long ordinal=inicio+k++;if(f.isBefore(desde))continue;String id=id(cfg,serie.getString("id"),ordinal);if(!existentes.contains(id)){r.add(virtual(serie,cfg,ordinal));if(r.size()>10000)throw new IllegalArgumentException("Acotá el período para mostrar las ocurrencias");}}}}}}catch(JSONException e){throw new IllegalStateException("No se pudo leer la recurrencia",e);}return r;}
 public static Registro ocurrencia(Context c,String serie,long ordinal){try(DatabaseHelper h=new DatabaseHelper(c)){JSONObject p=fila(h.getReadableDatabase(),"series_eventos",serie);if(p==null||!p.isNull("deleted_at"))return null;JSONObject cfg=configuracion(p);if(ordinal>=cfg.optLong("parar_antes",Long.MAX_VALUE))return null;Registro v=virtual(p,cfg,ordinal);if(!p.isNull("fecha_fin")&&LocalDate.parse(v.texto("fecha")).isAfter(LocalDate.parse(p.getString("fecha_fin"))))return null;JSONObject real=fila(h.getReadableDatabase(),"eventos",v.texto("id"));if(real!=null){if(!real.isNull("deleted_at"))return null;v=registro(real);anotar(h.getReadableDatabase(),v);}return v;}catch(JSONException e){throw new IllegalStateException(e);}}
 public static JSONObject reglaActual(Context c,Registro r){if(r.texto("serieId").isEmpty())return null;try(DatabaseHelper h=new DatabaseHelper(c)){JSONObject serie=fila(h.getReadableDatabase(),"series_eventos",r.texto("serieId"));if(serie==null)return null;JSONObject cfg=configuracion(serie);long ordinal=ordinal(h.getReadableDatabase(),r);JSONObject s=JsonSync.copia(segmentoEn(cfg,ordinal));s.put("frecuencia",serie.getString("frecuencia"));s.put("fecha_fin",serie.opt("fecha_fin"));return s;}catch(JSONException e){throw new IllegalStateException(e);}}
 private static long ordinal(SQLiteDatabase db,Registro r)throws JSONException{if(!r.texto("_ordinal").isEmpty())return Long.parseLong(r.texto("_ordinal"));JSONObject m=metadatos(db,r.texto("id"));if(m==null)throw new IllegalStateException("No se encontró el origen de esta ocurrencia");return m.getLong("ordinal");}
 public static void materializar(SQLiteDatabase db,Context c,String device,Registro r){try{iniciar(db);if(fila(db,"eventos",r.texto("id"))!=null)return;ContentValues v=valores(r);v.put("id",r.texto("id"));v.put("owner_id",r.get("ownerId"));v.put("revision",1);db.insertOrThrow("eventos",null,v);guardarIndice(db,r.texto("id"),new JSONObject().put("serie_id",r.texto("_serie")).put("ordinal",Long.parseLong(r.texto("_ordinal"))).put("fecha_origen",r.texto("_fechaOrigen")));CambiosEvento.registrar(db,device,"eventos",r.texto("id"),0,1,"UPSERT");}catch(JSONException e){throw new IllegalStateException(e);}}
 private static void escribirEvento(SQLiteDatabase db,String device,Registro r,boolean borrar)throws JSONException{JSONObject actual=fila(db,"eventos",r.texto("id"));int base=actual==null?0:actual.getInt("revision");ContentValues v=valores(r);v.put("owner_id",r.get("ownerId"));v.put("revision",base+1);v.put("updated_at",Instant.now().toString());if(borrar)v.put("deleted_at",Instant.now().toString());if(actual==null){v.put("id",r.texto("id"));db.insertOrThrow("eventos",null,v);}else db.update("eventos",v,"id=?",new String[]{r.texto("id")});if(!r.texto("_serie").isEmpty())guardarIndice(db,r.texto("id"),new JSONObject().put("serie_id",r.texto("_serie")).put("ordinal",Long.parseLong(r.texto("_ordinal"))).put("fecha_origen",r.texto("_fechaOrigen")));CambiosEvento.registrar(db,device,"eventos",r.texto("id"),base,base+1,borrar?"DELETE":"UPSERT");}
 private static void escribirSerie(SQLiteDatabase db,String device,String id,String owner,String frecuencia,JSONObject cfg,String fin,boolean borrar)throws JSONException{JSONObject actual=fila(db,"series_eventos",id);int base=actual==null?0:actual.getInt("revision");ContentValues v=new ContentValues();v.put("owner_id",owner);v.put("frecuencia",frecuencia);v.put("configuracion_personalizada",cfg.toString());v.put("fecha_fin",fin==null||fin.isEmpty()?null:fin);v.put("revision",base+1);v.put("updated_at",Instant.now().toString());if(borrar)v.put("deleted_at",Instant.now().toString());if(actual==null){v.put("id",id);db.insertOrThrow("series_eventos",null,v);}else db.update("series_eventos",v,"id=?",new String[]{id});CambiosEvento.registrar(db,device,"series_eventos",id,base,base+1,borrar?"DELETE":"UPSERT");}
 public static void guardar(Context c,Registro editado,Registro anterior,int alcance,String frecuencia,ReglaRecurrencia.Unidad unidad,int cada,String fin){guardarDatos(c,editado,anterior,alcance,frecuencia,unidad,cada,fin);cambios(c);}
 static void guardarDatos(Context c,Registro editado,Registro anterior,int alcance,String frecuencia,ReglaRecurrencia.Unidad unidad,int cada,String fin){String device=IdentidadLocal.dispositivo(c),owner=IdentidadLocal.propietario(c);try(DatabaseHelper h=new DatabaseHelper(c)){SQLiteDatabase db=h.getWritableDatabase();db.beginTransaction();try{iniciar(db);Registro r=editado.copia();JSONObject vigente=r.texto("id").isEmpty()?null:fila(db,"eventos",r.texto("id"));if(vigente!=null&&!anterior.texto("revision").isEmpty()&&vigente.getInt("revision")!=Integer.parseInt(anterior.texto("revision")))throw new IllegalStateException("El evento cambió. Volvé a abrirlo antes de guardar.");r.put("ownerId",owner);String serie=r.texto("serieId");boolean existente=!serie.isEmpty();if(r.texto("id").isEmpty())r.put("id",UUID.randomUUID().toString());if(!existente&&frecuencia.equals("NINGUNA")){escribirEvento(db,device,r,false);}else if(existente&&alcance==SOLO){escribirEvento(db,device,r,false);}else{
  long pivot=existente?ordinal(db,r):0;JSONObject actualSerie=existente?fila(db,"series_eventos",serie):null,cfg=existente?configuracion(actualSerie):new JSONObject().put("version",1).put("evento_inicial",r.texto("id"));JSONObject viejo=existente?JsonSync.copia(cfg):null;String oldFrecuencia=existente?actualSerie.getString("frecuencia"):frecuencia;
  if(!existente)serie=UUID.randomUUID().toString();LocalDate seleccionada=LocalDate.parse(r.texto("fecha"));if(fin!=null&&!fin.isEmpty()&&LocalDate.parse(fin).isBefore(seleccionada))throw new IllegalArgumentException("La finalización no puede ser anterior a esta ocurrencia");
  if(frecuencia.equals("NINGUNA")){cfg.put("parar_antes",alcance==TODAS?0:pivot);escribirSerie(db,device,serie,owner,oldFrecuencia,cfg,actualSerie.isNull("fecha_fin")?null:actualSerie.getString("fecha_fin"),false);}
  else{ReglaRecurrencia regla=alcance==TODAS?ReglaRecurrencia.desdeOcurrencia(seleccionada,pivot,unidad,cada):new ReglaRecurrencia(seleccionada,unidad,cada,seleccionada.getDayOfMonth(),seleccionada.getMonthValue());long desde=alcance==TODAS?0:pivot;JSONObject t=plantilla(r);JSONArray segmentos=new JSONArray();if(existente&&alcance==SIGUIENTES){JSONArray prev=cfg.getJSONArray("segmentos");for(int i=0;i<prev.length();i++)if(prev.getJSONObject(i).getLong("desde")<pivot)segmentos.put(prev.getJSONObject(i));}segmentos.put(segmento(desde,regla,t));cfg.put("segmentos",segmentos);cfg.remove("parar_antes");escribirSerie(db,device,serie,owner,frecuencia,cfg,fin,false);}
  if(existente){List<Registro>afectados=new ArrayList<>();try(Cursor rows=db.rawQuery("SELECT e.* FROM eventos e JOIN eventos_ocurrencias o ON o.evento_id=e.id WHERE o.serie_id=?",new String[]{serie})){while(rows.moveToNext()){Registro e=registro(JsonCursorHelper.toJsonObject(rows));anotar(db,e);afectados.add(e);}}
   for(Registro e:afectados){long indice=ordinal(db,e);if(alcance==SIGUIENTES&&indice<pivot||e.texto("id").equals(r.texto("id")))continue;boolean borrar=frecuencia.equals("NINGUNA");if(!borrar){LocalDate antes=fecha(viejo,indice),despues=fecha(cfg,indice);long offset=ChronoUnit.DAYS.between(antes,LocalDate.parse(e.texto("fecha")));e.put("fecha",despues.plusDays(offset).toString());if(fin!=null&&!fin.isEmpty()&&despues.isAfter(LocalDate.parse(fin)))borrar=true;for(String campo:CAMPOS)if(!Arrays.asList("fecha","serieId","estadoEspecial").contains(campo)&&!Objects.equals(anterior.get(campo),r.get(campo)))e.put(campo,r.get(campo));}if(!e.texto("deletedAt").isEmpty())continue;escribirEvento(db,device,e,borrar);}
  }
  r.put("serieId",frecuencia.equals("NINGUNA")?null:serie);r.put("_serie",serie);r.put("_ordinal",String.valueOf(pivot));r.put("_fechaOrigen",existente?fecha(viejo,pivot).toString():seleccionada.toString());escribirEvento(db,device,r,false);
 }
 editado.put("id",r.texto("id"));db.setTransactionSuccessful();}finally{db.endTransaction();}}catch(JSONException e){throw new IllegalStateException("No se pudo guardar la recurrencia",e);}}
 public static void eliminar(Context c,Registro r,int alcance){eliminarDatos(c,r,alcance);cambios(c);}
 static void eliminarDatos(Context c,Registro r,int alcance){String device=IdentidadLocal.dispositivo(c),owner=IdentidadLocal.propietario(c);try(DatabaseHelper h=new DatabaseHelper(c)){SQLiteDatabase db=h.getWritableDatabase();db.beginTransaction();try{iniciar(db);if(r.texto("serieId").isEmpty()||alcance==SOLO){Registro e=r.copia();e.put("ownerId",owner);escribirEvento(db,device,e,true);}else{String serie=r.texto("serieId");long pivot=ordinal(db,r);JSONObject s=fila(db,"series_eventos",serie),cfg=configuracion(s);if(alcance==SIGUIENTES)cfg.put("parar_antes",pivot);escribirSerie(db,device,serie,owner,s.getString("frecuencia"),cfg,s.isNull("fecha_fin")?null:s.getString("fecha_fin"),alcance==TODAS);List<Registro>lista=new ArrayList<>();try(Cursor rows=db.rawQuery("SELECT e.* FROM eventos e JOIN eventos_ocurrencias o ON o.evento_id=e.id WHERE o.serie_id=? AND e.deleted_at IS NULL",new String[]{serie})){while(rows.moveToNext()){Registro e=registro(JsonCursorHelper.toJsonObject(rows));anotar(db,e);lista.add(e);}}for(Registro e:lista)if(alcance==TODAS||ordinal(db,e)>=pivot)escribirEvento(db,device,e,true);}db.setTransactionSuccessful();}finally{db.endTransaction();}}catch(JSONException e){throw new IllegalStateException(e);}}
 public static void cambios(Context c){CoordinadorSync.de(c).solicitar(false,null);com.example.agendapersonal.avisos.ProgramadorAvisos.actualizar(c);}
}
